import SectorIntensityChart from "../components/charts/SectorIntensityChart.js";
import TopicPieChart from "../components/charts/TopicPieChart.js";
import RegionChart from "../components/charts/RegionChart.js";
import PestleChart from "../components/charts/PestleChart.js";
import insights from "../data/insights.json";

function Dashboard() {
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-6">
      <SectorIntensityChart data={insights} />
      <TopicPieChart data={insights} />
      <RegionChart data={insights} />
      <PestleChart data={insights} />
    </div>
  );
}

export default Dashboard;
